#!/bin/bash
# 007 smoke (1 GPU, dev): two twins, every 31st panel prompt (201); directions, scores, selection, ladder
# with small bootstraps, float32 path, one own-direction checkpoint generated by vLLM.
#   shell/nchc/submit.sh --dev --gpus 1 --time 02:00:00 --name 007-smoke -- bash shell/mech/smoke_007.sh
set -euo pipefail
W=/work/harrychang08/castor
S=$W/tmp/007-smoke
M=data/manifests/mech_007.json
A=dd-dclm-1b-default-dpo-seed1; B=dd-dclm-1b-large-aux-2-dpo-seed1
mkdir -p $S
for ID in $A $B; do
    uv run --frozen python scripts/extract_007.py --models $M --model-id $ID \
        --out $S/acts/$ID --panel-every 31
done
uv run --frozen python scripts/extract_007.py --models $M --model-id $A --dtype float32 \
    --out $S/acts-fp32/$A --panel-every 31
uv run --frozen python scripts/select_007.py --models $M --acts-root $S/acts \
    --out $S/selection.json --allow-subset
uv run --frozen python scripts/select_007.py --models $M --acts-root $S/acts \
    --out $S/selection_filtered.json --allow-subset --filtered
uv run --frozen python scripts/ladder_007.py --models $M --acts-root $S/acts \
    --selection $S/selection.json --selection-filtered $S/selection_filtered.json \
    --fp32 $S/acts-fp32/$A --out $S/ladder.json --n-boot 20 --n-boot-sec 5 \
    --panel-every 31 --allow-subset
uv run --frozen python scripts/ablate_007.py --models $M --model-id $A --kind own \
    --selection $S/selection.json --acts-root $S/acts --out $S/models/$A-own
uv run --frozen python scripts/ablate_007.py --models $M --model-id $A --kind random \
    --selection $S/selection.json --acts-root $S/acts --out $S/models/$A-random
uv run --frozen python scripts/generate.py --model $S/models/$A-own --model-id $A-ablate-own \
    --out-root $S/runs --prompt-id 007smoke --limit 40
echo SMOKE-OK
